export default function draw(g, t, k) {
  const { W, H, U, S, L, C, D, T, beat, BEAT } = k;
  const dur = beat.dur; // 1.607 s
  const words = beat.words; // ["COMPILE", "DEPLOY", "SHIP"]
  const light = k.light;

  // --- ground ---
  g.fillStyle = C.ink;
  g.fillRect(0, 0, W, H);

  // --- seeded rng for this frame ---
  const rng = k.rng(Math.floor(t * 24));

  // --- time windows per word (3 beats in 1.607s → ~0.536s each) ---
  const beatLen = dur / 3;
  const p0 = k.win(t, 0, beatLen);          // COMPILE
  const p1 = k.win(t, beatLen, beatLen * 2); // DEPLOY
  const p2 = k.win(t, beatLen * 2, dur);     // SHIP

  // --- tunnel parameters ---
  // The tunnel accelerates: speed ramps up
  const tunnelSpeed = k.lerp(0.3, 2.5, k.cine(k.clamp(t / dur)));
  const tunnelP = (t * tunnelSpeed) % 1;

  // --- data-stream tunnel background ---
  g.save();
  // Darken edges for tunnel feel
  const vignetteGrad = g.createRadialGradient(L.cx, H * 0.5, H * 0.25, L.cx, H * 0.5, H * 0.75);
  vignetteGrad.addColorStop(0, 'rgba(17,18,18,0)');
  vignetteGrad.addColorStop(0.5, 'rgba(17,18,18,0.3)');
  vignetteGrad.addColorStop(1, 'rgba(17,18,18,0.92)');
  g.fillStyle = vignetteGrad;
  g.fillRect(0, 0, W, H);
  g.restore();

  // --- tunnel lines: vertical streaks racing in ---
  const numLines = 60;
  for (let i = 0; i < numLines; i++) {
    const seed = i / numLines;
    const x = ((seed * 1.7 + tunnelP * 0.7) % 1) * W;
    const lineH = k.lerp(8, 80, k.noise1(i * 7.13 + t * 0.4) * 0.5 + 0.5);
    const y = ((k.noise1(i * 3.77 + t * 0.6) * 0.5 + 0.5) * H);
    const alpha = k.lerp(0.02, 0.12, k.noise1(i * 11.3 + t * 0.3) * 0.5 + 0.5);
    g.fillStyle = k.rgba(C.accent, alpha);
    g.fillRect(x - 0.5, y - lineH / 2, 1, lineH);
  }

  // --- horizontal scanlines ---
  g.save();
  g.globalAlpha = 0.04;
  for (let y = 0; y < H; y += 3) {
    g.fillStyle = C.accent;
    g.fillRect(0, y, W, 1);
  }
  g.restore();

  // --- progress bars racing along edges ---
  const barH = 3 * U;
  // Top bar
  const topProgress = (t * 1.8) % 1;
  g.fillStyle = k.rgba(C.accent, 0.25);
  g.fillRect(0, 0, W * topProgress, barH);
  g.fillStyle = k.rgba(C.accent, 0.7);
  g.fillRect(W * topProgress - 4, 0, 8, barH);

  // Bottom bar (reverse)
  const botProgress = (t * 2.1 + 0.3) % 1;
  g.fillStyle = k.rgba(C.accent, 0.25);
  g.fillRect(W * (1 - botProgress), H - barH, W * botProgress, barH);
  g.fillStyle = k.rgba(C.accent, 0.7);
  g.fillRect(W * (1 - botProgress) - 4, H - barH, 8, barH);

  // --- side brackets / trackers ---
  // Left tracker
  const trackerP = k.clamp(t / (dur * 0.15));
  k.tracker(g, t, 0, 40 * U, H * 0.35, 180 * U, 60 * U, 'SANDBOX', 'ACTIVE');
  // Right tracker
  k.tracker(g, t, 0.1, W - 220 * U, H * 0.55, 180 * U, 50 * U, 'PIPELINE', 'HOT');

  // --- sparks / embers in the tunnel ---
  k.sparks(g, t, 0, L.cx, H * 0.5, { n: 18, color: C.accent });
  k.sparks(g, t, 0.15, L.cx - 200 * U, H * 0.4, { n: 12, color: C.accent });
  k.sparks(g, t, 0.3, L.cx + 250 * U, H * 0.6, { n: 14, color: C.accent });

  // --- words: slam in, one per beat, left-to-right tracking ---
  const wordData = [
    { word: words[0], p: p0, idx: 0 },
    { word: words[1], p: p1, idx: 1 },
    { word: words[2], p: p2, idx: 2 },
  ];

  // Each word gets larger: COMPILE smallest, SHIP largest
  const baseSizes = [72, 96, 130];
  // X positions: left third, centre, right third
  const xPositions = [W * 0.22, L.cx, W * 0.78];

  for (const wd of wordData) {
    if (wd.p <= 0) continue;

    const { word, p, idx } = wd;
    const size = baseSizes[idx] * U;

    // Spring slam in
    const slam = k.sp(p, 'slam');
    // Fade in quickly
    const fade = k.clamp(p * 3);

    // Motion blur via horizontal streak offset
    const blurAmount = k.lerp(12, 3, slam) * (1 - k.clamp(p * 2 - 1)); // blur reduces as it settles

    // Draw motion-blurred streaks behind the word
    const cx = xPositions[idx];
    const cy = H * 0.5;
    const streakCount = 5;
    for (let s = 0; s < streakCount; s++) {
      const offset = (s + 1) * blurAmount * 3;
      const sa = fade * 0.08 * (1 - s / streakCount);
      if (sa <= 0.001) continue;
      g.save();
      g.globalAlpha = sa;
      g.fillStyle = C.accent;
      g.font = `${D.weight} ${size}px ${D.family}`;
      g.textAlign = 'center';
      g.textBaseline = 'middle';
      g.fillText(word, cx - offset, cy);
      g.restore();
    }

    // Main word
    const scale = k.lerp(0.7, 1.0, slam);
    g.save();
    g.globalAlpha = fade;
    g.translate(cx, cy);
    g.scale(scale, scale);
    g.fillStyle = C.bone;
    g.font = `${D.weight} ${size}px ${D.family}`;
    g.textAlign = 'center';
    g.textBaseline = 'middle';
    g.fillText(word, 0, 0);

    // Accent glow under the word
    if (slam > 0.5) {
      const glowAlpha = (slam - 0.5) * 2 * fade * 0.35;
      const m = g.measureText(word);
      const tw = m.width;
      k.glow(g, 0, 0, tw * 0.6, C.accent, glowAlpha);
    }

    g.restore();

    // Decoding brackets around the word
    if (slam > 0.6) {
      const m = g.measureText(word);
      const tw = m.width * scale;
      const bw = tw * 0.55;
      const bh = size * scale * 0.65;
      const bp = (slam - 0.6) / 0.4;
      k.bracket(g, cx, cy, bw, bh, { p: bp, color: C.accent, width: 2 * U });
    }
  }

  // --- extra tunnel depth: horizontal streaks at word heights ---
  for (const wd of wordData) {
    if (wd.p <= 0.3) continue;
    const y = H * 0.5;
    const streakLen = k.lerp(60, 300, wd.p);
    const sa = k.clamp((wd.p - 0.3) / 0.5) * 0.15;
    k.streak(g, xPositions[wd.idx] + 40 * U, y, streakLen * U, 1.5 * U, C.accent, sa);
    k.streak(g, xPositions[wd.idx] - 40 * U, y, -streakLen * U, 1.5 * U, C.accent, sa);
  }

  // --- HUD crosshair pulses on each word beat ---
  for (let i = 0; i < 3; i++) {
    const beatT = beatLen * i + beatLen * 0.5;
    const cp = k.win(t, beatT - 0.05, beatT + 0.15);
    if (cp > 0) {
      const fade = cp < 0.5 ? cp * 2 : (1 - cp) * 2;
      k.crosshair(g, xPositions[i], H * 0.5, 18 * U, { p: fade, color: C.accent });
    }
  }

  // --- scanning line effect ---
  const scanY = ((t * 0.7) % 1) * H;
  g.save();
  g.globalAlpha = 0.06;
  g.fillStyle = C.accent;
  g.fillRect(0, scanY - 1, W, 2);
  g.restore();

  // --- corner brackets (HUD frame) ---
  const cornerP = k.clamp(t / 0.2);
  const corners = [
    { x: S.x, y: S.y, dx: 1, dy: 1 },
    { x: S.x + S.w, y: S.y, dx: -1, dy: 1 },
    { x: S.x, y: S.y + S.h, dx: 1, dy: -1 },
    { x: S.x + S.w, y: S.y + S.h, dx: -1, dy: -1 },
  ];
  for (const c of corners) {
    const len = 40 * U;
    g.strokeStyle = k.rgba(C.accent, cornerP * 0.5);
    g.lineWidth = 2 * U;
    g.beginPath();
    g.moveTo(c.x, c.y - c.dy * len);
    g.lineTo(c.x, c.y);
    g.lineTo(c.x + c.dx * len, c.y);
    g.stroke();
  }

  // --- dust in the tunnel ---
  k.dust(g, W, H, t, {
    n: 30,
    size: 2 * U,
    inBeam: () => true,
  });
}
